mapper.select:
SELECT s.id, s.order_id AS orderId, s.shipment_date AS shipmentDate, s.tracking_no AS trackingNo, s.confirmed AS confirmed, s.remark AS remark, s.created_at AS createdAt, s.updated_at AS updatedAt FROM shipments s
AND s.confirmed = 1
AND s.shipment_date >= #{from}
AND s.shipment_date <= #{to}
ORDER BY s.shipment_date ASC
